<?php
function list_brands($pdo){$rows=$pdo->query('SELECT id,name FROM brands ORDER BY name')->fetchAll();$out=array();foreach($rows as $b)$out[]=array('id'=>(int)$b['id'],'name'=>$b['name']);json_response($out);}
function list_products($pdo){$where=array();$values=array();foreach(array('brand_id'=>'p.brand_id','gender'=>'p.gender','mechanism'=>'p.mechanism')as$q=>$c)if(isset($_GET[$q])&&$_GET[$q]!==''){$where[]=$c.'=?';$values[]=$_GET[$q];}if(isset($_GET['brand'])&&$_GET['brand']!==''){$where[]='b.name=?';$values[]=$_GET['brand'];}foreach(array('price_min'=>'>=','price_max'=>'<=')as$q=>$op)if(isset($_GET[$q])&&is_numeric($_GET[$q])){$where[]='p.price '.$op.' ?';$values[]=$_GET[$q];}$sqlWhere=$where?' WHERE '.implode(' AND ',$where):'';$sorts=array('price_asc'=>'p.price ASC','price_desc'=>'p.price DESC','name_asc'=>'p.title ASC','name_desc'=>'p.title DESC');$sort=isset($_GET['sort'])&&isset($sorts[$_GET['sort']])?$sorts[$_GET['sort']]:'p.id DESC';$page=max(1,(int)(isset($_GET['page'])?$_GET['page']:1));$limit=min(100,max(1,(int)(isset($_GET['limit'])?$_GET['limit']:20)));$count=$pdo->prepare('SELECT COUNT(*) FROM products p LEFT JOIN brands b ON b.id=p.brand_id'.$sqlWhere);$count->execute($values);$total=(int)$count->fetchColumn();$s=$pdo->prepare('SELECT p.*,b.name brand FROM products p LEFT JOIN brands b ON b.id=p.brand_id'.$sqlWhere.' ORDER BY '.$sort.' LIMIT '.$limit.' OFFSET '.(($page-1)*$limit));$s->execute($values);$data=array();foreach($s->fetchAll()as$p)$data[]=product_response($pdo,$p);json_response(array('data'=>$data,'pagination'=>array('page'=>$page,'limit'=>$limit,'total'=>$total,'total_pages'=>(int)ceil($total/$limit))));}
